// live-build shim: marimo hosts anywidgets in a shadow root, so emotion (MUI)
// styles injected into document.head never reach the widget. Mirror them into
// the shadow root, and keep the widget hidden until the mirror is complete so
// it never flashes unstyled.
function __liveSyncEmotion(root){
  let tag=root.querySelector("style[data-live-emotion]");
  if(!tag){tag=document.createElement("style");tag.setAttribute("data-live-emotion","");root.prepend(tag);}
  let css="",count=0;
  for(const sheet of document.styleSheets){
    const owner=sheet.ownerNode;
    if(owner&&owner.getAttribute&&owner.getAttribute("data-emotion")!==null){
      try{for(const r of sheet.cssRules){css+=r.cssText+"\n";count++;}}catch{}
    }
  }
  if(tag.__ruleCount!==count){tag.textContent=css;tag.__ruleCount=count;}
  return count;
}
export default{
  render(ctx){
    const root=ctx.el.getRootNode();
    let iv=null,revealed=false;
    if(root&&root.host){
      ctx.el.style.visibility="hidden";
      const reveal=()=>{if(!revealed){revealed=true;ctx.el.style.visibility="";}};
      let last=-1,stable=0;
      const tick=()=>{
        const count=__liveSyncEmotion(root);
        stable=count>0&&count===last?stable+1:0;
        last=count;
        if(stable>=3){reveal();iv=setInterval(()=>__liveSyncEmotion(root),400);}
        else requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
      setTimeout(reveal,3000);
    }
    const res=xne(ctx);
    const wrap=(cleanup)=>()=>{if(iv)clearInterval(iv);if(typeof cleanup==="function")cleanup();};
    if(res&&typeof res.then==="function")return res.then(wrap);
    return wrap(res);
  }
};
